#!/bin/sh
# Rebuild the two Dolby Vision tunnel test frames (run on a box with an Intel
# GPU and the YBLOD Vulkan engine; we used Ollie's UHD 770 and the
# yblod-sync-root image = YBLOD 0.3.2/0.3.3 engine, golden-hash identical).
#
#   make-frames.sh WORKDIR
#
# Output in WORKDIR: dv-ref.xrgb(.zst) and dv-bad.xrgb(.zst), raw 3840x2160
# XRGB8888 (B,G,R,X). No film content: the picture is FFmpeg's testsrc2 and
# the RPU is generated by dovi_tool from refclip-gen.json.
set -eu
W=${1:?usage: make-frames.sh WORKDIR}
HERE=$(cd "$(dirname "$0")" && pwd)
DOVI=${DOVI_TOOL:-dovi_tool}
mkdir -p "$W"; cd "$W"
"$DOVI" generate -j "$HERE/refclip-gen.json" -o rpu.bin
ffmpeg -hide_banner -loglevel error -y -f lavfi -i "testsrc2=s=3840x2160:r=24000/1001:d=2" \
  -vf "format=yuv420p10le,lutyuv=y=val*0.72+40:u=val:v=val" -c:v libx265 -preset fast -crf 18 \
  -x265-params "colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc:range=limited:hdr10=1:repeat-headers=1:master-display=G(13250,34500)B(7500,3000)R(34000,16000)WP(15635,16450)L(10000000,1):max-cll=1000,300:log-level=error" \
  -f hevc base.hevc
"$DOVI" inject-rpu -i base.hevc --rpu-in rpu.bin -o p81.hevc
mkvmerge -q -o nuclab-dv-p81.mkv --default-duration 0:24000/1001p p81.hevc
# The engine as YBLOD's Kodi runs it by default (CB1 contract), picture 6.
docker run --rm --device /dev/dri -v "$W:/clip" yblod-sync-root \
  dvvk-bench --cb1 --frames 12 --rate 0 --dump-at 6 --dump /clip/dv-ref.xrgb /clip/nuclab-dv-p81.mkv
python3 -I "$HERE/tunnelcheck.py" check dv-ref.xrgb
python3 -I "$HERE/tunnelcheck.py" corrupt dv-ref.xrgb dv-bad.xrgb
sha256sum dv-ref.xrgb dv-bad.xrgb
for f in dv-ref dv-bad; do zstd -q -19 -T0 -f $f.xrgb -o $f.xrgb.zst; done
